create extension if not exists pgcrypto;create table if not exists public.enquiries(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 120),email text not null check(char_length(email)<=254),phone text not null default '',course text not null default '',message text not null default '',kind text not null default 'enrollment' check(kind in('enrollment','contact','workshop')),status text not null default 'new' check(status in('new','in_progress','responded','closed')),created_at timestamptz not null default now());alter table public.enquiries enable row level security;revoke all on public.enquiries from anon,authenticated;grant all on public.enquiries to service_role;-- No browser-side policies: server-only service role writes.